{
  "aggregate_id": "DEF-NRS-484A-305::truck",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The contract describes a human-powered device, which the vehicle definition excludes and the motor-vehicle requirement therefore does not admit."
    },
    {
      "class": "ru.bus",
      "verdict": "supported",
      "reason": "Passenger-carrying design alone does not establish admission, and every bus satisfying the goods-use and purpose-built-body requirements also satisfies the quoted ru.truck contract."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person rather than a motor vehicle, so the admitting words reach no member."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "Commercial mass or licensing alone does not establish admission, and every admitted member has the motor-vehicle, goods-carrying and purpose-built-body features of ru.truck."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "Electric bicycles are expressly excluded from both vehicle and motor vehicle, preventing admission under the truck definition."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "Electric scooters are expressly excluded from both vehicle and motor vehicle, preventing admission under the truck definition."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "Emergency designation does not establish the required goods use or body design, and every admitted member satisfies the quoted ru.truck contract."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "supported",
      "reason": "Fire-fighting function does not establish the required goods use or body design, and every admitted member satisfies the quoted ru.truck contract."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The words do not categorically exclude mopeds, and any admitted moped must have the motor-vehicle, goods-carrying and purpose-built-body features of ru.truck."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "Self-propulsion and non-rail operation alone are insufficient, while every member meeting the additional goods-use and body requirements satisfies the quoted ru.truck contract."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "Wheel count and astride riding do not settle admission, and every motorcycle meeting the goods-use and purpose-built-body requirements satisfies the quoted ru.truck contract."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Official or contracted road service does not establish admission, and every admitted member satisfies the quoted ru.truck contract."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract describes a person rather than the device carrying that person, so the motor-vehicle admitting words reach no member."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "A pedestrian carrying a cane or accompanied by a guide remains a person rather than a motor vehicle, so no member is admitted."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "The contract describes on-track equipment, which fails the express requirement that a motor vehicle not be operated upon rails."
    },
    {
      "class": "ru.school_bus",
      "verdict": "supported",
      "reason": "School designation and markings do not establish the goods-use and body requirements, and every admitted school bus satisfies the quoted ru.truck contract."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "Passenger-for-hire status and markings do not establish admission, and every admitted taxicab satisfies the quoted ru.truck contract."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "supported",
      "reason": "Tour, shuttle or limousine characteristics do not establish admission, and every admitted member satisfies the quoted ru.truck contract."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "contradicted",
      "reason": "Any member admitted by the truck definition necessarily satisfies the ru.truck contract, so uncertainty about whether a combination qualifies does not prevent complete coverage by the proposed included class."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "supported",
      "reason": "Public transit service and identifying displays do not establish admission, and every admitted transit bus satisfies the quoted ru.truck contract."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "The admitting clause matches the contract's goods-carrying motor vehicle with a body built for that purpose, and no posted exception removes that class."
    }
  ]
}

